def panel(sample):
    if sample is None:
        return ['EMPTY PAD']
    name = ''.join(c if 32 <= ord(c) <= 126 else '?'
                   for c in sample['name'])[:17]
    seconds = sample['frames'] / sample['rate']
    return [name, f"SRC {sample['bpm']:.2f} ST",
            f"LEN {seconds:.2f}s", 'G:1 L:0 R:0']

sample = {'name': 'Dry kick', 'frames': 60000,
          'rate': 48000, 'bpm': 120}
assert panel(None) == ['EMPTY PAD']
assert len(panel({**sample, 'name': 'abcdefghijklmnopqr'})[0]) == 17
print('\n'.join(panel(sample)))

